(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_0RB1LD_1LC1RB_1RD1LA_0LC0LC : NeverQuasiHaltsTr tm_0RB1LD_1LC1RB_1RD1LA_0LC0LC.
Proof.
  apply (boardph_neverqhtr tm_0RB1LD_1LC1RB_1RD1LA_0LC0LC pins_0RB1LD_1LC1RB_1RD1LA_0LC0LC FAM 1
                           iarm_0RB1LD_1LC1RB_1RD1LA_0LC0LC 0 1
                           farm_0RB1LD_1LC1RB_1RD1LA_0LC0LC 1 1
                           fm1_0RB1LD_1LC1RB_1RD1LA_0LC0LC fm2_0RB1LD_1LC1RB_1RD1LA_0LC0LC 0 vis_0RB1LD_1LC1RB_1RD1LA_0LC0LC
                           [0] 0 19).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
