Import WrapTr LadderCheckTr.
Import LapGlueTr.
Import LadderCheckLiftTr.
Import ListNotations.

Definition mk_1RB0LC_0RC0RC_0LD1RA_1RC1LD (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB0LC_0RC0RC_0LD1RA_1RC1LD.

(** 1RB0LC_0RC0RC_0LD1RA_1RC1LD *)
Definition tm_1RB0LC_0RC0RC_0LD1RA_1RC1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S0 DR StC
  | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StD
  | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DR StC
  | StD, S1 => mk S1 DL StD
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0LC_0RC0RC_0LD1RA_1RC1LD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0LC_0RC0RC_0LD1RA_1RC1LD pins_1RB0LC_0RC0RC_0LD1RA_1RC1LD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LC_0RC0RC_0LD1RA_1RC1LD : Fam := mkFam 2 [[S0;S1;S1];[S1;S1;S1]] [] [[S1]] Binary 1 [mkFill 1 [] 0 [] 0] StC S0 true [].
Local Notation FAM := fam_1RB0LC_0RC0RC_0LD1RA_1RC1LD.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LC_0RC0RC_0LD1RA_1RC1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) (mkC StC (mkS [S0;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 5, [RB (SWin 5)])].
Local Notation lad := lad_1RB0LC_0RC0RC_0LD1RA_1RC1LD.

Definition rules_1RB0LC_0RC0RC_0LD1RA_1RC1LD : list LRule := map fst lad.
Local Notation rules := rules_1RB0LC_0RC0RC_0LD1RA_1RC1LD.

Lemma ladder_ok_1RB0LC_0RC0RC_0LD1RA_1RC1LD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_0RC0RC_0LD1RA_1RC1LD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_0RC0RC_0LD1RA_1RC1LD. Qed.

(** ** The arms, as DATA

