Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LC_0RC0RC_0LD1RA_1RC1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_0RC0RC_0LD1RA_1RC1LD
  | 0, 1 => iarm0_1_1RB0LC_0RC0RC_0LD1RA_1RC1LD
  | _, _ => iarm0_0_1RB0LC_0RC0RC_0LD1RA_1RC1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

