Lemma ladder_ok_1RB0LC_1LA1RD_0RA1LC_1RA0LB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_1LA1RD_0RA1LC_1RA0LB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_1LA1RD_0RA1LC_1RA0LB. Qed.

